class Tx {                              // RAII: scope-bound transaction
    sqlite3* db; bool done = false;
public:
    explicit Tx(sqlite3* d) : db(d) { exec(db, "BEGIN"); }
    ~Tx() { if (!done) exec(db, "ROLLBACK"); }
    void commit() { exec(db, "COMMIT"); done = true; }
};
